/*
 * A332766  Numbers k for which there exists a group of order k that cannot be
 *          generated by A051903(k) elements.
 * https://oeis.org/A332766
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th k such that some prime q has exponent A051903(k) in
 *            k and some prime p dividing k has p | q-1 (search over k)
 * Range:     u8 n <= 59, u16 n <= 59, u32 n <= 59, u64 n <= 59, u128 n <= 59,
 *            big any n
 * Validated: partial, pass, 59 terms through n = 59 (2026-11-08)
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/factor_u64.h"

static bool A332766_member(uint64_t k)
{
    if (k <= 1)
        return false;
    uint64_t pr[64];
    uint64_t ex[64];
    size_t cnt = 0;
    factor_u64(k, pr, ex, &cnt);
    uint64_t e = 0;
    for (size_t i = 0; i < cnt; ++i)
        if (ex[i] > e)
            e = ex[i];
    for (size_t i = 0; i < cnt; ++i) {
        if (ex[i] != e)
            continue;
        for (size_t j = 0; j < cnt; ++j) {
            if (j == i)
                continue;
            if ((pr[i] - 1) % pr[j] == 0)
                return true;
        }
    }
    return false;
}

seq_t a(idx_t n)
{
    uint64_t count = 0;
    uint64_t k = 1;
    while (count < (uint64_t)n) {
        ++k;
        if (A332766_member(k))
            ++count;
    }
    return (seq_t)k;
}
